package com.smartproperty.platform.parking.controller;
import com.smartproperty.platform.parking.dto.*;import com.smartproperty.platform.parking.service.ParkingPermitService;import com.smartproperty.platform.parking.vo.*;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;import java.util.List;
@RestController @RequestMapping("/api/resident/me/parking-permits") public class ResidentParkingPermitController {private final ParkingPermitService service;public ResidentParkingPermitController(ParkingPermitService s){service=s;}@GetMapping("/eligibilities")public List<ParkingEligibilityVO> eligibilities(){return service.myEligibilities();}@GetMapping("/vehicles")public List<VehicleVO> vehicles(){return service.myVehicles();}@PostMapping("/vehicles")public VehicleVO createVehicle(@Valid @RequestBody CreateVehicleRequest r){return service.createMyVehicle(r);}@GetMapping("/applications")public List<ParkingPermitApplicationVO> applications(){return service.myApplications();}@GetMapping public List<ParkingPermitVO> permits(){return service.myPermits();}@PostMapping("/applications")public ParkingPermitApplicationVO apply(@Valid @RequestBody SubmitParkingPermitApplicationRequest r){return service.submitMyApplication(r);}}
